diff --git a/durability.go b/durability.go
new file mode 100644
index 00000000..c9b4bf93
--- /dev/null
+++ b/durability.go
@@ -0,0 +1,544 @@
+// Copyright 2024 The LevelDB-Go and Pebble Authors. All rights reserved. Use
+// of this source code is governed by a BSD-style license that can be found in
+// the LICENSE file.
+
+package pebble
+
+import (
+	"context"
+	"sync"
+	"time"
+
+	"github.com/cockroachdb/crlib/crtime"
+	"github.com/cockroachdb/errors"
+	"github.com/cockroachdb/pebble/internal/base"
+)
+
+var (
+	// ErrDurabilityJobExpired is returned when waiting for a job ID that is
+	// outside the bounded retention window.
+	ErrDurabilityJobExpired = errors.New("pebble: durability job expired")
+
+	// ErrDurabilityJobUnknown is returned when waiting for a job ID that was
+	// never seen or is zero.
+	ErrDurabilityJobUnknown = errors.New("pebble: durability job unknown")
+
+	// ErrDurabilitySubscriptionLimitExceeded is returned when the maximum number
+	// of outstanding DurabilityNotify subscriptions is exceeded.
+	ErrDurabilitySubscriptionLimitExceeded = errors.New("pebble: durability subscription limit exceeded")
+)
+
+// DurabilityStats provides a snapshot of the database's durability metrics.
+type DurabilityStats struct {
+	HighestDurableSeqNum   base.SeqNum
+	FirstErr               error
+	PendingWaiters         int64
+	TotalDurableCommits    uint64
+	TotalFailedCommits     uint64
+	CumulativeSyncDuration time.Duration
+	MaxSyncDuration        time.Duration
+}
+
+type durabilitySubscription struct {
+	seqNum base.SeqNum
+	ch     chan error
+}
+
+type syncCommit struct {
+	jobID         int
+	seqNum        base.SeqNum
+	count         uint32
+	batchSize     int
+	correlationID uint64
+	syncStart     crtime.Mono
+	walWG         sync.WaitGroup
+	walErr        error
+	origWG        *sync.WaitGroup
+	origErr       *error
+	applyDone     chan struct{}
+	applyDuration time.Duration
+}
+
+type durabilityManager struct {
+	mu   sync.Mutex
+	cond sync.Cond
+
+	highestDurableSeqNum base.SeqNum
+	firstErr             error
+	closed               bool
+	closeErr             error
+
+	pendingWaiters int64
+
+	totalDurableCommits    uint64
+	totalFailedCommits     uint64
+	cumulativeSyncDuration time.Duration
+	maxSyncDuration        time.Duration
+
+	// Job ID tracking.
+	nextJobID        int
+	maxAssignedJobID int
+	maxEvictedJobID  int
+	pendingJobs      map[int]struct{}
+	retainedJobs     map[int]error
+	retainedOrder    []int
+	maxRetainedJobs  int
+
+	// Subscriptions for DurabilityNotify.
+	outstandingSubscriptions int
+	maxSubscriptions         int
+	subscriptions            []durabilitySubscription
+
+	// Notification channel for context-aware waiters.
+	notifyCh chan struct{}
+}
+
+func newDurabilityManager(opts *Options) *durabilityManager {
+	maxRetained := 1024
+	if opts != nil && opts.Experimental.DurabilityJobRetentionWindow > 0 {
+		maxRetained = opts.Experimental.DurabilityJobRetentionWindow
+	}
+	maxSubs := 4096
+	if opts != nil && opts.Experimental.MaxDurabilitySubscriptions > 0 {
+		maxSubs = opts.Experimental.MaxDurabilitySubscriptions
+	}
+
+	m := &durabilityManager{
+		pendingJobs:      make(map[int]struct{}),
+		retainedJobs:     make(map[int]error),
+		maxRetainedJobs:  maxRetained,
+		maxSubscriptions: maxSubs,
+		notifyCh:         make(chan struct{}),
+	}
+	m.cond.L = &m.mu
+	return m
+}
+
+func (m *durabilityManager) allocJobID() int {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+	m.nextJobID++
+	id := m.nextJobID
+	m.maxAssignedJobID = id
+	m.pendingJobs[id] = struct{}{}
+	return id
+}
+
+func (m *durabilityManager) recordCommit(sc *syncCommit, syncDuration time.Duration) {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+
+	delete(m.pendingJobs, sc.jobID)
+	m.retainedJobs[sc.jobID] = sc.walErr
+	m.retainedOrder = append(m.retainedOrder, sc.jobID)
+
+	for len(m.retainedOrder) > m.maxRetainedJobs {
+		evicted := m.retainedOrder[0]
+		m.retainedOrder = m.retainedOrder[1:]
+		delete(m.retainedJobs, evicted)
+		if evicted > m.maxEvictedJobID {
+			m.maxEvictedJobID = evicted
+		}
+	}
+
+	if sc.walErr != nil {
+		m.totalFailedCommits++
+		if m.firstErr == nil {
+			m.firstErr = sc.walErr
+		}
+		m.cumulativeSyncDuration += syncDuration
+		if syncDuration > m.maxSyncDuration {
+			m.maxSyncDuration = syncDuration
+		}
+	} else {
+		m.totalDurableCommits++
+		m.cumulativeSyncDuration += syncDuration
+		if syncDuration > m.maxSyncDuration {
+			m.maxSyncDuration = syncDuration
+		}
+		lastSeq := sc.seqNum
+		if sc.count > 0 {
+			lastSeq = sc.seqNum + base.SeqNum(sc.count) - 1
+		}
+		if lastSeq > m.highestDurableSeqNum {
+			m.highestDurableSeqNum = lastSeq
+		}
+	}
+
+	m.notifySubscriptionsLocked()
+
+	close(m.notifyCh)
+	m.notifyCh = make(chan struct{})
+	m.cond.Broadcast()
+}
+
+func (m *durabilityManager) notifySubscriptionsLocked() {
+	var remaining []durabilitySubscription
+	for _, sub := range m.subscriptions {
+		if (sub.seqNum == 0 && (m.totalDurableCommits > 0 || m.highestDurableSeqNum > 0)) ||
+			(sub.seqNum > 0 && sub.seqNum <= m.highestDurableSeqNum) {
+			sub.ch <- nil
+			m.outstandingSubscriptions--
+		} else if m.firstErr != nil {
+			sub.ch <- m.firstErr
+			m.outstandingSubscriptions--
+		} else if m.closed {
+			sub.ch <- m.closeErr
+			m.outstandingSubscriptions--
+		} else {
+			remaining = append(remaining, sub)
+		}
+	}
+	m.subscriptions = remaining
+}
+
+func (m *durabilityManager) Close(closeErr error) {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+
+	if m.closed {
+		return
+	}
+	m.closed = true
+	m.closeErr = closeErr
+
+	m.notifySubscriptionsLocked()
+
+	close(m.notifyCh)
+	m.notifyCh = make(chan struct{})
+	m.cond.Broadcast()
+}
+
+func (d *DB) durabilityLoop() {
+	defer close(d.durabilityLoopDone)
+	for {
+		select {
+		case <-d.closedCh:
+			d.drainDurabilityQueue()
+			return
+		case sc := <-d.durabilityQueue:
+			d.processSyncCommit(sc)
+		}
+	}
+}
+
+func (d *DB) processSyncCommit(sc *syncCommit) {
+	// 1. Wait for WAL sync to complete on disk.
+	sc.walWG.Wait()
+	syncDuration := max(time.Nanosecond, sc.syncStart.Elapsed())
+	if sc.origErr != nil {
+		*sc.origErr = sc.walErr
+	}
+
+	// 2. Wait for apply to memtable to complete.
+	<-sc.applyDone
+
+	// 3. Update durability manager state.
+	d.durability.recordCommit(sc, syncDuration)
+
+	// 4. Accumulate metrics if BatchDurable was configured.
+	if d.batchDurableConfigured && sc.walErr == nil {
+		d.durableCommitCount.Add(1)
+		d.durableCommitDuration.Add(int64(syncDuration))
+	}
+
+	// 5. Fire EventListener.BatchDurable callback exactly once.
+	info := BatchDurableInfo{
+		JobID:         sc.jobID,
+		SeqNum:        sc.seqNum,
+		Err:           sc.walErr,
+		ApplyDuration: sc.applyDuration,
+		SyncDuration:  syncDuration,
+		CorrelationID: sc.correlationID,
+		BatchSize:     sc.batchSize,
+		KeyCount:      sc.count,
+	}
+	d.opts.EventListener.BatchDurable(info)
+
+	// 6. Signal committer / sync waiter.
+	if sc.origWG != nil {
+		sc.origWG.Done()
+	}
+}
+
+func (d *DB) drainDurabilityQueue() {
+	for {
+		select {
+		case sc := <-d.durabilityQueue:
+			d.processSyncCommit(sc)
+		default:
+			return
+		}
+	}
+}
+
+// WaitForDurability blocks until the given sequence number is durable.
+// A sequence number of zero succeeds after any commit.
+func (d *DB) WaitForDurability(seqNum base.SeqNum) error {
+	return d.WaitForDurabilityContext(context.Background(), seqNum)
+}
+
+// WaitForDurabilityContext blocks until the given sequence number is durable or
+// the context is cancelled. Durability and close errors take precedence over
+// context cancellation.
+func (d *DB) WaitForDurabilityContext(ctx context.Context, seqNum base.SeqNum) error {
+	if d.opts.DisableWAL {
+		return nil
+	}
+
+	d.durability.mu.Lock()
+
+	// Check if already closed or error latched.
+	if d.durability.closed {
+		err := d.durability.closeErr
+		d.durability.mu.Unlock()
+		return err
+	}
+	if d.durability.firstErr != nil {
+		err := d.durability.firstErr
+		d.durability.mu.Unlock()
+		return err
+	}
+
+	// Check if already durable.
+	if seqNum == 0 {
+		if d.durability.totalDurableCommits > 0 || d.durability.highestDurableSeqNum > 0 {
+			d.durability.mu.Unlock()
+			return nil
+		}
+	} else if seqNum <= d.durability.highestDurableSeqNum {
+		d.durability.mu.Unlock()
+		return nil
+	}
+
+	// Must block. Increment pendingWaiters.
+	d.durability.pendingWaiters++
+	defer func() {
+		d.durability.pendingWaiters--
+		d.durability.mu.Unlock()
+	}()
+
+	var ctxDone <-chan struct{}
+	if ctx != nil {
+		ctxDone = ctx.Done()
+	}
+
+	for {
+		if (seqNum == 0 && (d.durability.totalDurableCommits > 0 || d.durability.highestDurableSeqNum > 0)) ||
+			(seqNum > 0 && seqNum <= d.durability.highestDurableSeqNum) {
+			return nil
+		}
+		if d.durability.firstErr != nil {
+			return d.durability.firstErr
+		}
+		if d.durability.closed {
+			return d.durability.closeErr
+		}
+
+		ch := d.durability.notifyCh
+		d.durability.mu.Unlock()
+
+		select {
+		case <-ctxDone:
+			d.durability.mu.Lock()
+			// Durability/close errors take precedence over context cancellation.
+			if (seqNum == 0 && (d.durability.totalDurableCommits > 0 || d.durability.highestDurableSeqNum > 0)) ||
+				(seqNum > 0 && seqNum <= d.durability.highestDurableSeqNum) {
+				return nil
+			}
+			if d.durability.firstErr != nil {
+				return d.durability.firstErr
+			}
+			if d.durability.closed {
+				return d.durability.closeErr
+			}
+			return ctx.Err()
+		case <-ch:
+			d.durability.mu.Lock()
+		}
+	}
+}
+
+// WaitForDurabilityBatch blocks until every sequence number in the slice is durable.
+// A nil or empty slice returns nil immediately.
+func (d *DB) WaitForDurabilityBatch(seqNums []base.SeqNum) error {
+	return d.WaitForDurabilityBatchContext(context.Background(), seqNums)
+}
+
+// WaitForDurabilityBatchContext blocks until every sequence number in the slice is durable
+// or the context is cancelled. Durability and close errors take precedence over context cancellation.
+func (d *DB) WaitForDurabilityBatchContext(ctx context.Context, seqNums []base.SeqNum) error {
+	if len(seqNums) == 0 {
+		return nil
+	}
+	if d.opts.DisableWAL {
+		return nil
+	}
+
+	var maxSeq base.SeqNum
+	for _, s := range seqNums {
+		if s > maxSeq {
+			maxSeq = s
+		}
+	}
+
+	if maxSeq == 0 {
+		return d.WaitForDurabilityContext(ctx, 0)
+	}
+	return d.WaitForDurabilityContext(ctx, maxSeq)
+}
+
+// WaitForJobDurability blocks until the commit with the given callback job ID is durable.
+// Jobs outside a bounded retention window return an expired error. Never-seen and zero
+// IDs return an unknown error.
+func (d *DB) WaitForJobDurability(jobID int) error {
+	return d.WaitForJobDurabilityContext(context.Background(), jobID)
+}
+
+// WaitForJobDurabilityContext blocks until the commit with the given callback job ID is durable
+// or the context is cancelled. Durability and close errors take precedence over context cancellation.
+func (d *DB) WaitForJobDurabilityContext(ctx context.Context, jobID int) error {
+	if d.opts.DisableWAL {
+		return nil
+	}
+
+	d.durability.mu.Lock()
+
+	// Fast paths / validation.
+	if jobID <= 0 || jobID > d.durability.maxAssignedJobID {
+		d.durability.mu.Unlock()
+		return ErrDurabilityJobUnknown
+	}
+
+	if jobID <= d.durability.maxEvictedJobID {
+		d.durability.mu.Unlock()
+		return ErrDurabilityJobExpired
+	}
+
+	if err, ok := d.durability.retainedJobs[jobID]; ok {
+		d.durability.mu.Unlock()
+		return err
+	}
+
+	if _, ok := d.durability.pendingJobs[jobID]; !ok {
+		d.durability.mu.Unlock()
+		return ErrDurabilityJobUnknown
+	}
+
+	// Job is currently pending in-flight. Increment pendingWaiters.
+	d.durability.pendingWaiters++
+	defer func() {
+		d.durability.pendingWaiters--
+		d.durability.mu.Unlock()
+	}()
+
+	var ctxDone <-chan struct{}
+	if ctx != nil {
+		ctxDone = ctx.Done()
+	}
+
+	for {
+		if err, ok := d.durability.retainedJobs[jobID]; ok {
+			return err
+		}
+		if jobID <= d.durability.maxEvictedJobID {
+			return ErrDurabilityJobExpired
+		}
+		if d.durability.closed {
+			return d.durability.closeErr
+		}
+
+		ch := d.durability.notifyCh
+		d.durability.mu.Unlock()
+
+		select {
+		case <-ctxDone:
+			d.durability.mu.Lock()
+			// Durability/close errors take precedence over context cancellation.
+			if err, ok := d.durability.retainedJobs[jobID]; ok {
+				return err
+			}
+			if jobID <= d.durability.maxEvictedJobID {
+				return ErrDurabilityJobExpired
+			}
+			if d.durability.closed {
+				return d.durability.closeErr
+			}
+			return ctx.Err()
+		case <-ch:
+			d.durability.mu.Lock()
+		}
+	}
+}
+
+// DurableState returns the highest durable sequence number and the first latched error.
+func (d *DB) DurableState() (base.SeqNum, error) {
+	if d.opts.DisableWAL {
+		return 0, nil
+	}
+	d.durability.mu.Lock()
+	defer d.durability.mu.Unlock()
+	return d.durability.highestDurableSeqNum, d.durability.firstErr
+}
+
+// DurabilityNotify returns a pre-filled receive-only channel that delivers nil on success
+// or a non-nil error on WAL sync failure or DB close. Outstanding subscriptions are bounded;
+// excess callers get a pre-filled channel with an immediate non-nil error.
+func (d *DB) DurabilityNotify(seqNum base.SeqNum) <-chan error {
+	ch := make(chan error, 1)
+
+	if d.opts.DisableWAL {
+		ch <- nil
+		return ch
+	}
+
+	d.durability.mu.Lock()
+	defer d.durability.mu.Unlock()
+
+	if d.durability.closed {
+		ch <- d.durability.closeErr
+		return ch
+	}
+
+	if d.durability.firstErr != nil {
+		ch <- d.durability.firstErr
+		return ch
+	}
+
+	if seqNum == 0 {
+		if d.durability.totalDurableCommits > 0 || d.durability.highestDurableSeqNum > 0 {
+			ch <- nil
+			return ch
+		}
+	} else if seqNum <= d.durability.highestDurableSeqNum {
+		ch <- nil
+		return ch
+	}
+
+	if d.durability.outstandingSubscriptions >= d.durability.maxSubscriptions {
+		ch <- ErrDurabilitySubscriptionLimitExceeded
+		return ch
+	}
+
+	d.durability.outstandingSubscriptions++
+	d.durability.subscriptions = append(d.durability.subscriptions, durabilitySubscription{
+		seqNum: seqNum,
+		ch:     ch,
+	})
+	return ch
+}
+
+// DurabilityStats returns a snapshot of durability statistics.
+func (d *DB) DurabilityStats() DurabilityStats {
+	d.durability.mu.Lock()
+	defer d.durability.mu.Unlock()
+	return DurabilityStats{
+		HighestDurableSeqNum:   d.durability.highestDurableSeqNum,
+		FirstErr:               d.durability.firstErr,
+		PendingWaiters:         d.durability.pendingWaiters,
+		TotalDurableCommits:    d.durability.totalDurableCommits,
+		TotalFailedCommits:     d.durability.totalFailedCommits,
+		CumulativeSyncDuration: d.durability.cumulativeSyncDuration,
+		MaxSyncDuration:        d.durability.maxSyncDuration,
+	}
+}
